public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    for (ProfileAnalyzeTimeRange range : timeRanges) {

        // read the file line by line and parse the snapshots
        BufferedReader reader = new BufferedReader(new FileReader(file));

        String line = reader.readLine();

        while (line != null) {

            // extract the thread name and format from the line
            int idx = line.indexOf(":");

            String threadName = line.substring(0, idx);

            String format = line.substring(idx + 1);

            // check if the thread name matches the range
            if (range.getStartTime() <= Double.parseDouble(threadName) && Double.parseDouble(threadName) <= range.getEndTime()) {
                ThreadSnapshot snapshot = new ThreadSnapshot();
                snapshot.setThreadName(threadName);
                snapshot.setFormat(format);
                threadSnapshots.add(snapshot);
            }

            line = reader.readLine();
        }

        reader.close();
    }

    return threadSnapshots;
}
